// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;

    function setUp() public { c = new BANK_SAFE(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        CountingLogger logger = new CountingLogger();
        vm.prank(address(this));
        c.SetLogFile(address(logger));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        assertTrue(logger.count() == 1 && logger.lastVal() == amount && logger.lastSender() == actor);
    }
}

contract CountingLogger {
    uint public count;
    uint public lastVal;
    address public lastSender;

    function AddMessage(address _adr, uint _val, string calldata) external {
        count += 1;
        lastVal = _val;
        lastSender = _adr;
    }
}
